/* 학습 해설
 * Devres 전체 반환: 목록에서 분리한 뒤 역순 정리하기
 * 드라이버 분리 시 후반에 얻은 자원이 앞서 얻은 자원에 의존할 수 있습니다. 일반 자원을 등록 역순으로 정리하면 이런 의존성을 풀 수 있고, callback을 목록 spinlock 밖에서 실행하면 긴 정리가 잠금 구간에 들어가지 않습니다.
 * devres_release_all은 devres_head.next가 NULL이면 경고와 -ENODEV입니다. 빈 목록이면0입니다. 그 외에는 IRQ-safe 잠금 아래 전체 범위를 remove_nodes로 todo에 분리하고 잠금을 푼 뒤 release_nodes로 정리합니다. 반환은 해제한 일반 자원 수입니다. 그룹 노드도 같은 정리 경로에서 다뤄지지만 식별용 release는 아무 동작도 하지 않습니다.
 * A를 얻고 그 위에 B, 다시 C를 얻었다면 일반 자원 callback 순서는 C→B→A입니다. 반환3은 errno3이라는 뜻이 아니라 자원 세 개를 처리했다는 뜻입니다. callback이 해제할 실제 하드웨어 상태와 외부 할당은 각 release 구현의 책임이며 관리 객체 메모리는 이후 kfree됩니다.
 */
int devres_release_all(struct device *dev)
{
	unsigned long flags;
	LIST_HEAD(todo);
	int cnt;

	/* Looks like an uninitialized device structure */
	if (WARN_ON(dev->devres_head.next == NULL))
		return -ENODEV;

	/* Nothing to release if list is empty */
	if (list_empty(&dev->devres_head))
		return 0;

	spin_lock_irqsave(&dev->devres_lock, flags);
	cnt = remove_nodes(dev, dev->devres_head.next, &dev->devres_head, &todo);
	spin_unlock_irqrestore(&dev->devres_lock, flags);

	release_nodes(dev, &todo);
	return cnt;
}

/**
 * devres_open_group - Open a new devres group
 * @dev: Device to open devres group for
 * @id: Separator ID
 * @gfp: Allocation flags
 *
 * Open a new devres group for @dev with @id.  For @id, using a
 * pointer to an object which won't be used for another group is
 * recommended.  If @id is NULL, address-wise unique ID is created.
 *
 * RETURNS:
 * ID of the new group, NULL on failure.
 */

