/* 학습 해설
 * Devm 메모리: 0바이트 특수 포인터와 비어 있는 release
 * 메모리 자체를 관리 자원에 포함하면 드라이버 분리 때 별도 free 분기를 줄일 수 있습니다. 다만 일반 kmalloc처럼 크기0과 초기화 플래그의 의미를 정확히 구분해야 합니다.
 * devm_kmalloc은 size=0이면 ZERO_SIZE_PTR을 반환하며 실제 관리 항목을 만들지 않습니다. 나머지는 dev_to_node의 node에서 alloc_dr를 호출하고 실패는 NULL입니다. 진단 이름·크기를 기록하고 devres_add로 등록한 data를 반환합니다. release callback devm_kmalloc_release는 비어 있지만 최종 devres 해제에서 관리 객체와 data가 한 할당으로 kfree되므로 메모리는 정리됩니다.
 * 진단 문자열이 devm_kzalloc_release라고 적혀 있어도 원문은 역사적 이름이라고 설명합니다. 실제0초기화는 전달 gfp와 alloc_dr의 __GFP_ZERO 처리에 달려 있으므로 devm_kmalloc이 언제나 데이터를0으로 만든다고 할 수 없습니다. ZERO_SIZE_PTR은 NULL과 다른 특별 반환값이며 정상 데이터를 역참조할 포인터가 아닙니다.
 */
void *devm_kmalloc(struct device *dev, size_t size, gfp_t gfp)
{
	struct devres *dr;

	if (unlikely(!size))
		return ZERO_SIZE_PTR;

	/* use raw alloc_dr for kmalloc caller tracing */
	dr = alloc_dr(devm_kmalloc_release, size, gfp, dev_to_node(dev));
	if (unlikely(!dr))
		return NULL;

	/*
	 * This is named devm_kzalloc_release for historical reasons
	 * The initial implementation did not support kmalloc, only kzalloc
	 */
	set_node_dbginfo(&dr->node, "devm_kzalloc_release", size);
	devres_add(dev, dr->data);
	return dr->data;
}
EXPORT_SYMBOL_GPL(devm_kmalloc);

/**
 * devm_krealloc - Resource-managed krealloc()
 * @dev: Device to re-allocate memory for
 * @ptr: Pointer to the memory chunk to re-allocate
 * @new_size: New allocation size
 * @gfp: Allocation gfp flags
 *
 * Managed krealloc(). Resizes the memory chunk allocated with devm_kmalloc().
 * Behaves similarly to regular krealloc(): if @ptr is NULL or ZERO_SIZE_PTR,
 * it's the equivalent of devm_kmalloc(). If new_size is zero, it frees the
 * previously allocated memory and returns ZERO_SIZE_PTR. This function doesn't
 * change the order in which the release callback for the re-alloc'ed devres
 * will be called (except when falling back to devm_kmalloc() or when freeing
 * resources when new_size is zero). The contents of the memory are preserved
 * up to the lesser of new and old sizes.
 */

