/* 학습 해설
 * Devm 문자열·메모리 복사: 끝의 NUL과 rodata 재사용
 * C 문자열의 길이는 끝을 표시하는0바이트를 제외합니다. 문자열로 다시 사용하려면 끝 표시까지 복사해야 하지만 일반 메모리는 중간에0이 있을 수 있어 길이를 별도로 받아야 합니다.
 * devm_kstrdup은 입력 s가 NULL이면 NULL입니다. strlen(s)+1만큼 devm_kmalloc하고 성공하면 그 전체 크기를 memcpy하므로 끝 NUL도 복사합니다. devm_kstrdup_const는 is_kernel_rodata이면 원래 s를 그대로 반환하고 아니면 일반 문자열 복사로 갑니다. devm_kmemdup은 문자열 길이를 찾지 않고 len바이트를 할당하고 성공 시 그 길이만 복사합니다.
 * 문자열 cat은 문자3개지만 필요한 공간은 NUL까지4바이트입니다. 바이트 배열 [65,0,66]을 len3으로 kmemdup하면 세 바이트 모두 복사됩니다. strlen 기반 문자열 복사는 중간0을 끝으로 보므로 같은 작업이 아닙니다. const 복사의 rodata 경로는 새 관리 항목이나 새 문자열을 만들지 않습니다.
 */
char *devm_kstrdup(struct device *dev, const char *s, gfp_t gfp)
{
	size_t size;
	char *buf;

	if (!s)
		return NULL;

	size = strlen(s) + 1;
	buf = devm_kmalloc(dev, size, gfp);
	if (buf)
		memcpy(buf, s, size);
	return buf;
}
EXPORT_SYMBOL_GPL(devm_kstrdup);

/**
 * devm_kstrdup_const - resource managed conditional string duplication
 * @dev: device for which to duplicate the string
 * @s: the string to duplicate
 * @gfp: the GFP mask used in the kmalloc() call when allocating memory
 *
 * Strings allocated by devm_kstrdup_const will be automatically freed when
 * the associated device is detached.
 *
 * RETURNS:
 * Source string if it is in .rodata section otherwise it falls back to
 * devm_kstrdup.
 */

