/* 학습 해설
 * Devm 페이지 할당: 실제 페이지와 정리 기록을 따로 얻기
 * 페이지 묶음은 해제할 때 시작 주소뿐 아니라 order도 필요합니다. 자동 정리 기록에 그 정보를 저장하면 호출자가 조기 해제 시 order를 다시 전달하지 않아도 됩니다. 대신 실제 페이지와 기록의 두 할당 실패를 모두 처리해야 합니다.
 * devm_get_free_pages는 __get_free_pages(gfp_mask,order)를 먼저 호출하고 주소0이면 실패0입니다. 다음으로 pages_devres를 GFP_KERNEL로 할당하며 실패하면 방금 얻은 페이지를 free_pages(addr,order)하고0입니다. 성공하면 주소와 order를 기록하고 devres_add 후 주소를 반환합니다. release helper는 저장된 두 값으로 free_pages를 호출합니다. match는 주소만 비교합니다.
 * order2는4페이지입니다. 설명용4KiB 페이지 시스템이면 총16KiB입니다. devm_free_pages는 주소를 검색 조건으로 devres_release하므로 caller가 order를 넘기지 않아도 저장된 값으로 해제합니다. 항목이 없으면 WARN_ON이며 실제 자원을 찾았다고 가정해 다른 주소를 무작정 해제하지 않습니다.
 */
unsigned long devm_get_free_pages(struct device *dev,
				  gfp_t gfp_mask, unsigned int order)
{
	struct pages_devres *devres;
	unsigned long addr;

	addr = __get_free_pages(gfp_mask, order);

	if (unlikely(!addr))
		return 0;

	devres = devres_alloc(devm_pages_release,
			      sizeof(struct pages_devres), GFP_KERNEL);
	if (unlikely(!devres)) {
		free_pages(addr, order);
		return 0;
	}

	devres->addr = addr;
	devres->order = order;

	devres_add(dev, devres);
	return addr;
}
EXPORT_SYMBOL_GPL(devm_get_free_pages);

