/* 학습 해설
 * Devm CPU별 메모리: 포인터를 담은 관리 기록과 실제 대상
 * CPU별 메모리를 각 CPU의 작업에 나눠 사용할 수 있지만 그 메모리를 정리하려면 실제 per-CPU 할당을 반환해야 합니다. 포인터를 저장한 작은 관리 기록만 해제하면 실제 메모리가 남습니다.
 * __devm_alloc_percpu는 __alloc_percpu(size,align)을 먼저 호출하고 실패하면 NULL입니다. 다음으로 포인터 하나 크기의 관리 기록을 GFP_KERNEL로 할당하며 실패하면 free_percpu 후 NULL입니다. 성공하면 기록 안에 pcpu 포인터를 저장하고 등록한 뒤 실제 pcpu를 반환합니다. release는 기록에서 그 포인터를 꺼내 free_percpu를 호출하고 match는 기록에 담긴 포인터와 요청 대상을 비교합니다.
 * devm_free_percpu는 devres_release로 찾아 제거하고 실제 release까지 실행합니다. devres_destroy만 쓰면 포인터를 담은 기록만 해제되어 per-CPU 메모리가 누수되므로 원문 주석이 release 사용 이유를 명시합니다. 여기의 per-CPU 포인터는 일반 연속 버퍼처럼 임의로 역참조하는 주소와 구분해야 하며 실제 접근은 per-CPU API의 계약을 따릅니다.
 */
void __percpu *__devm_alloc_percpu(struct device *dev, size_t size,
		size_t align)
{
	void *p;
	void __percpu *pcpu;

	pcpu = __alloc_percpu(size, align);
	if (!pcpu)
		return NULL;

	p = devres_alloc(devm_percpu_release, sizeof(void *), GFP_KERNEL);
	if (!p) {
		free_percpu(pcpu);
		return NULL;
	}

	*(void __percpu **)p = pcpu;

	devres_add(dev, p);

	return pcpu;
}
EXPORT_SYMBOL_GPL(__devm_alloc_percpu);

/**
 * devm_free_percpu - Resource-managed free_percpu
 * @dev: Device this memory belongs to
 * @pdata: Per-cpu memory to free
 *
 * Free memory allocated with devm_alloc_percpu().
 */

