/* 학습 해설
 * ANY 주소 판정: 주소0과 포트0을 구별하기
 * 소켓 주소에는 주소 종류, IP 주소, 포트 같은 여러 필드가 함께 들어갑니다. 특정 함수를 읽을 때 구조체 전체가 아니라 어떤 필드로 조건을 판단하는지 확인해야 합니다. ANY 주소 여부를 포트나 접속 가능성과 혼동하면 잘못된 분기를 만들 수 있습니다.
 * inet_addr_is_any는 AF_INET6이면 주소16바이트를 IN6ADDR_ANY_INIT의0들과 memcmp하고 같으면 true입니다. AF_INET이면 sin_addr.s_addr를 htonl(INADDR_ANY)와 비교합니다. 다른 family는 경고하고 false입니다. 지원되는 family라도 주소가 ANY가 아니면 마지막 false로 갑니다.
 * 0.0.0.0:80과 0.0.0.0:443은 포트가 달라도 모두 true입니다. 127.0.0.1:0은 포트가0이지만 주소가0이 아니므로 false입니다. IPv6 ::도 true이고 ::1은 false입니다. 이 예시는 입력 sockaddr의 family와 실제 구조체 형태가 서로 맞는 것을 전제로 합니다.
 */
bool inet_addr_is_any(struct sockaddr *addr)
{
	if (addr->sa_family == AF_INET6) {
		struct sockaddr_in6 *in6 = (struct sockaddr_in6 *)addr;
		const struct sockaddr_in6 in6_any =
			{ .sin6_addr = IN6ADDR_ANY_INIT };

		if (!memcmp(in6->sin6_addr.s6_addr,
			    in6_any.sin6_addr.s6_addr, 16))
			return true;
	} else if (addr->sa_family == AF_INET) {
		struct sockaddr_in *in = (struct sockaddr_in *)addr;

		if (in->sin_addr.s_addr == htonl(INADDR_ANY))
			return true;
	} else {
		pr_warn("unexpected address family %u\n", addr->sa_family);
	}

	return false;
}
EXPORT_SYMBOL(inet_addr_is_any);

