/* 학습 해설
 * Nofault 커널 복사: 예외 복구와 정렬별 전송 단위
 * 진단 코드가 확실하지 않은 주소를 읽을 때 일반 페이지 폴트 처리로 잠들거나 복잡한 복구를 시작하면 실행 문맥에 맞지 않을 수 있습니다. nofault는 주소가 반드시 유효하다는 보증이 아니라 접근 실패를 정해진 오류 경로로 돌리는 방식입니다.
 * copy_from_kernel_nofault는 allowed(src,size)가 거짓이면 -ERANGE입니다. 기본 weak 구현은 true지만 아키텍처가 대체할 수 있습니다. 그 뒤 pagefault_disable하고 정렬 조건에 따라 u64,u32,u16,u8 순서로 복사합니다. 각 매크로는 성공한 단위만큼 두 포인터를 전진시키고 남은 길이를 줄입니다. 정상 종료는 pagefault_enable과0, Efault는 enable과 -EFAULT입니다.
 * 효율적 비정렬 접근 설정이 없으면 두 주소를 OR해 하위 비트로 공통 정렬을 판정합니다. 둘 다8바이트 정렬이고 길이13이면8+4+1바이트 순서입니다. 한 주소라도 홀수면 큰 단위를 건너뛰고1바이트씩 처리합니다. 설정이 있으면 align=0을 유지해 큰 단위를 허용합니다. 실패 전에 복사한 앞부분은 되돌리지 않습니다.
 */
long copy_from_kernel_nofault(void *dst, const void *src, size_t size)
{
	unsigned long align = 0;

	if (!IS_ENABLED(CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS))
		align = (unsigned long)dst | (unsigned long)src;

	if (!copy_from_kernel_nofault_allowed(src, size))
		return -ERANGE;

	pagefault_disable();
	if (!(align & 7))
		copy_from_kernel_nofault_loop(dst, src, size, u64, Efault);
	if (!(align & 3))
		copy_from_kernel_nofault_loop(dst, src, size, u32, Efault);
	if (!(align & 1))
		copy_from_kernel_nofault_loop(dst, src, size, u16, Efault);
	copy_from_kernel_nofault_loop(dst, src, size, u8, Efault);
	pagefault_enable();
	return 0;
Efault:
	pagefault_enable();
	return -EFAULT;
}
EXPORT_SYMBOL_GPL(copy_from_kernel_nofault);

