/* 학습 해설
 * Nofault 사용자 복사: 접근 범위와 남은 바이트의 오류 변환
 * 사용자 주소가 허용된 범위 안에 있다는 것과 실제로 모든 바이트에 접근할 수 있다는 것은 다릅니다. 범위 검사를 통과해도 페이지가 없거나 접근이 실패할 수 있으므로 복사 결과를 다시 검사해야 합니다.
 * copy_from_user_nofault는 __access_ok가 거짓이거나 nmi_uaccess_okay가 거짓이면 -EFAULT입니다. 그 뒤 폴트를 금지하고 __copy_from_user_inatomic을 호출한 후 다시 허용합니다. 내부 반환은 남은 바이트 수이고 wrapper는 비0을 -EFAULT,0을 성공0으로 바꿉니다. copy_to_user_nofault는 access_ok가 참일 때만 쓰기를 시도하며 이 본문에는 별도의 nmi_uaccess_okay 검사가 없습니다.
 * 요청8바이트 중 내부에서5바이트만 복사해3을 반환하면 공개 wrapper의 반환은3이 아니라 -EFAULT입니다. 이미 바뀐5바이트는 남을 수 있습니다. __copy_from_user_inatomic은 일반 copy_from_user와 달리 실패한 나머지를0으로 채우지 않으므로 오류를 무시하고8바이트 전부 초기화됐다고 사용하면 안 됩니다.
 */
long copy_from_user_nofault(void *dst, const void __user *src, size_t size)
{
	long ret = -EFAULT;

	if (!__access_ok(src, size))
		return ret;

	if (!nmi_uaccess_okay())
		return ret;

	pagefault_disable();
	ret = __copy_from_user_inatomic(dst, src, size);
	pagefault_enable();

	if (ret)
		return -EFAULT;
	return 0;
}
EXPORT_SYMBOL_GPL(copy_from_user_nofault);

