/* 학습 해설
 * Nofault 사용자 문자열: 빈 문자열의 반환0과 길이 측정
 * 같은 문자열 함수처럼 보여도 반환 길이에 NUL을 포함하는지, 빈 문자열과 오류를 어떻게 표시하는지 다를 수 있습니다. 주석의 요약만 보고 모든 경우에1을 더한다고 가정하면 버전별 경계 동작을 놓칩니다.
 * strncpy_from_user_nofault는 count<=0이면0입니다. 폴트를 금지해 strncpy_from_user를 호출한 뒤 enable합니다. ret>=count이면 ret=count와 dst[ret-1]=NUL,0<ret<count이면 ret을1 늘립니다. ret==0이나 음수는 그대로 반환합니다. 일반 helper가 빈 문자열에0을 반환하므로 이 v6.12 wrapper도 빈 문자열에0을 반환합니다.
 * 입력 ab와 충분한 count에서는 내부2가 외부3이 됩니다. 빈 문자열은 내부0이 외부0으로 남으므로 NUL 포함 길이는 항상1 이상이라는 일반화가 틀립니다. count3에 abcdef라면 외부는 dst[2]를 NUL로 만들고3을 반환합니다. 음수 실패 분기는 wrapper에서 추가 NUL을 강제하지 않습니다.
 */
long strncpy_from_user_nofault(char *dst, const void __user *unsafe_addr,
			      long count)
{
	long ret;

	if (unlikely(count <= 0))
		return 0;

	pagefault_disable();
	ret = strncpy_from_user(dst, unsafe_addr, count);
	pagefault_enable();

	if (ret >= count) {
		ret = count;
		dst[ret - 1] = '\0';
	} else if (ret > 0) {
		ret++;
	}

	return ret;
}

