/* 학습 해설
 * Swap 캐시 배출: 슬롯 반환과 배열 해제를 구별하기
 * 캐시를 잠시 끌 때는 비축한 슬롯만 전역 풀에 반환하면 되지만 CPU가 사라지는 경우에는 슬롯을 담던 배열 메모리도 해제해야 합니다. 캐시 내용과 캐시 저장 공간을 구분해야 재활성화와 CPU 제거를 같은 함수로 처리할 수 있습니다.
 * SLOTS_CACHE를 요청하면 alloc_lock 아래 slots+cur부터 nr개를 반환하고 cur,nr를0으로 만듭니다. free_slots가 참이면 배열도 kvfree하고 포인터를 NULL로 합니다. SLOTS_CACHE_RET는 free_lock을 IRQ 비활성화와 함께 잡아 n_ret개를 반환합니다. 배열까지 없앨 때는 포인터를 임시 변수에 옮기고 NULL로 만든 뒤 spinlock을 풀고 kvfree합니다.
 * cur=3,nr=2인 할당 캐시는 배열의3번과4번 슬롯을 반환합니다. 이미 소비한0~2번까지 다시 반환하지 않습니다. 일반 deactivate는 free_slots=false라 배열을 남겨 재사용합니다. CPU 해제 callback인 free_slot_cache는 전역 mutex를 잡고 두 종류를 free_slots=true로 배출한 뒤0입니다.
 */
static void drain_slots_cache_cpu(unsigned int cpu, unsigned int type,
				  bool free_slots)
{
	struct swap_slots_cache *cache;
	swp_entry_t *slots = NULL;

	cache = &per_cpu(swp_slots, cpu);
	if ((type & SLOTS_CACHE) && cache->slots) {
		mutex_lock(&cache->alloc_lock);
		swapcache_free_entries(cache->slots + cache->cur, cache->nr);
		cache->cur = 0;
		cache->nr = 0;
		if (free_slots && cache->slots) {
			kvfree(cache->slots);
			cache->slots = NULL;
		}
		mutex_unlock(&cache->alloc_lock);
	}
	if ((type & SLOTS_CACHE_RET) && cache->slots_ret) {
		spin_lock_irq(&cache->free_lock);
		swapcache_free_entries(cache->slots_ret, cache->n_ret);
		cache->n_ret = 0;
		if (free_slots && cache->slots_ret) {
			slots = cache->slots_ret;
			cache->slots_ret = NULL;
		}

