/* 학습 해설
 * Swap 슬롯 반환: 반환 묶음을 곧바로 재사용하지 않는 이유
 * 사용한 슬롯을 각 CPU의 할당 목록으로 바로 되돌리면 전역 풀에서 인접한 빈 슬롯들을 모을 기회가 줄어들 수 있습니다. 이 구현은 반환용 배열에 모았다가 전역 풀로 돌려보내 조각화를 줄이는 방향을 택합니다.
 * free_swap_slot은 먼저 zswap_invalidate(entry)를 호출합니다. 캐시 사용 가능하고 반환 배열이 있으면 free_lock을 잡고 두 조건을 다시 검사합니다. 잠금을 기다리는 사이 캐시가 꺼졌다면 직접 반환합니다. n_ret가 캐시 크기 이상이면 기존 묶음을 swapcache_free_entries로 반환하고0으로 한 뒤 새 entry를 배열에 추가합니다.
 * 설명용 크기B=4에서 n_ret=3이면 새 슬롯을 넣어4로 만들고 끝납니다. 다음 반환이 들어왔을 때 기존4개를 전역 풀로 비우고 새1개를 남깁니다. 채워지는 순간 즉시 비우는 조건이 아니라 추가 전에 기존 배열이 가득 찼는지 확인하는 조건입니다. 캐시를 사용하지 못하면 entry 한 개를 직접 전역 반환합니다.
 */
void free_swap_slot(swp_entry_t entry)
{
	struct swap_slots_cache *cache;

	/* Large folio swap slot is not covered. */
	zswap_invalidate(entry);

	cache = raw_cpu_ptr(&swp_slots);
	if (likely(use_swap_slot_cache && cache->slots_ret)) {
		spin_lock_irq(&cache->free_lock);
		/* Swap slots cache may be deactivated before acquiring lock */
		if (!use_swap_slot_cache || !cache->slots_ret) {
			spin_unlock_irq(&cache->free_lock);
			goto direct_free;
		}
		if (cache->n_ret >= SWAP_SLOTS_CACHE_SIZE) {
			/*
			 * Return slots to global pool.
			 * The current swap_map value is SWAP_HAS_CACHE.
			 * Set it to 0 to indicate it is available for
			 * allocation in global pool
			 */
			swapcache_free_entries(cache->slots_ret, cache->n_ret);
			cache->n_ret = 0;
		}
		cache->slots_ret[cache->n_ret++] = entry;

