/* 학습 해설
 * NAPI 예약: 이미 실행 중인 요청을 MISSED로 기억하기
 * 패킷마다 인터럽트에서 모든 수신 처리를 하면 한 장치가 CPU를 오래 차지할 수 있습니다. NAPI는 처리 작업을 예약해 한 번에 제한된 양을 poll합니다. 이미 예약된 작업에 새 요청이 겹칠 때 같은 인스턴스를 중복 실행하지 않으면서 새 요청도 놓치지 않아야 합니다.
 * napi_schedule_prep는 state를 읽고 DISABLE이면 false입니다. 그렇지 않으면 SCHED를 더한 새 상태를 만들고 기존에 SCHED가 있었다면 MISSED도 더합니다. try_cmpxchg가 실패하면 갱신된 val로 다시 계산합니다. 성공 뒤 기존 SCHED가 없었을 때만 true를 반환합니다.
 * 처음 SCHED0인 상태에서 CPU A가 성공하면 SCHED1,true입니다. 이어 CPU B가 요청하면 SCHED1을 유지하면서 MISSED1로 바꾸고 false입니다. B의 false는 상태를 아무것도 바꾸지 않았다는 뜻이 아니라 새 poll 예약권은 얻지 못했지만 재요청 표시를 남겼다는 뜻입니다.
 */
bool napi_schedule_prep(struct napi_struct *n)
{
	unsigned long new, val = READ_ONCE(n->state);

	do {
		if (unlikely(val & NAPIF_STATE_DISABLE))
			return false;
		new = val | NAPIF_STATE_SCHED;

		/* Sets STATE_MISSED bit if STATE_SCHED was already set
		 * This was suggested by Alexander Duyck, as compiler
		 * emits better code than :
		 * if (val & NAPIF_STATE_SCHED)
		 *     new |= NAPIF_STATE_MISSED;
		 */
		new |= (val & NAPIF_STATE_SCHED) / NAPIF_STATE_SCHED *
						   NAPIF_STATE_MISSED;
	} while (!try_cmpxchg(&n->state, &val, new));

	return !(val & NAPIF_STATE_SCHED);
}
EXPORT_SYMBOL(napi_schedule_prep);

