/* 학습 해설
 * NAPI 완료: MISSED 재예약과 타이머 기반 지연
 * poll이 현재 할 일을 끝내는 순간 새 수신 요청이 겹칠 수 있습니다. 그냥 SCHED를 지우면 이미 들어온 추가 작업이 남을 수 있어 완료 함수도 예약 함수와 같은 상태 전이를 조정해야 합니다.
 * napi_complete_done은 NPSVC 또는 IN_BUSY_POLL이면 false로 바로 반환합니다. 일반 경로에서는 work_done과 GRO 상태로 timeout과 IRQ 지연 횟수를 계산하고 GRO/일반 묶음을 처리합니다. poll_list에 남아 있으면 IRQ 보호 아래 제거하고 list_owner=-1로 합니다. 비교 교환으로 SCHED,MISSED,스레드 예약,선호 busy-poll 비트를 정리하되 기존 MISSED가 있으면 SCHED를 다시 남깁니다.
 * SCHED1,MISSED1이었다면 새 상태는 SCHED1,MISSED0이며 __napi_schedule로 다시 예약하고 false입니다. MISSED가 없다면 timeout이 있을 때 상대·CPU 고정 hrtimer를 시작합니다. IRQ 지연 횟수가 남고 timeout도 있으면 ret=false가 될 수 있으므로 false를 단일 오류 코드처럼 해석하면 안 됩니다.
 */
bool napi_complete_done(struct napi_struct *n, int work_done)
{
	unsigned long flags, val, new, timeout = 0;
	bool ret = true;

	/*
	 * 1) Don't let napi dequeue from the cpu poll list
	 *    just in case its running on a different cpu.
	 * 2) If we are busy polling, do nothing here, we have
	 *    the guarantee we will be called later.
	 */
	if (unlikely(n->state & (NAPIF_STATE_NPSVC |
				 NAPIF_STATE_IN_BUSY_POLL)))
		return false;

	if (work_done) {
		if (n->gro_bitmask)
			timeout = READ_ONCE(n->dev->gro_flush_timeout);
		n->defer_hard_irqs_count = READ_ONCE(n->dev->napi_defer_hard_irqs);
	}
	if (n->defer_hard_irqs_count > 0) {
		n->defer_hard_irqs_count--;
		timeout = READ_ONCE(n->dev->gro_flush_timeout);
		if (timeout)
			ret = false;
	}

