/* 학습 해설
 * NAPI poll 예산: 정확히 다 쓴 경우의 재처리 계약
 * 수신량이 많은 한 장치가 CPU를 독점하지 않도록 poll 한 번의 수신 처리량을 제한합니다. 처리량이 예산과 정확히 같은 경우에는 더 일이 남았는지 반환 숫자만으로 구분할 수 없어 특별한 약속이 필요합니다.
 * __napi_poll은 weight를 예산으로 삼고 예약 상태일 때 드라이버 poll을 호출하며 trace와 XDP flush 확인을 수행합니다. work>weight면 경고하고 work<weight면 반환합니다. 예산을 다 썼으면 disable 대기,busy-poll 선호를 먼저 처리합니다. 그 외 GRO와 일반 목록을 정리하고 이미 재예약된 목록이면 경고 후 반환하며 아니면 repoll=true입니다.
 * 예산64에서 work20이면 빠른 반환,work64이면 계속 처리할 후보입니다. 정확히64개로 모든 일을 끝냈어도 문서는 완료를 호출하지 않고 다음 poll을 기다리거나 완료 후63을 반환하는 방식을 설명합니다. 예산0 호출에서는 수신/XDP/page-pool 처리를 하면 안 되고 napi_complete_done도 호출하지 말아야 합니다. skb 송신 완료 처리는 별도 계약으로 남습니다.
 */
static int __napi_poll(struct napi_struct *n, bool *repoll)
{
	int work, weight;

	weight = n->weight;

	/* This NAPI_STATE_SCHED test is for avoiding a race
	 * with netpoll's poll_napi().  Only the entity which
	 * obtains the lock and sees NAPI_STATE_SCHED set will
	 * actually make the ->poll() call.  Therefore we avoid
	 * accidentally calling ->poll() when NAPI is not scheduled.
	 */
	work = 0;
	if (napi_is_scheduled(n)) {
		work = n->poll(n, weight);
		trace_napi_poll(n, work, weight);

		xdp_do_check_flushed(n);
	}

	if (unlikely(work > weight))
		netdev_err_once(n->dev, "NAPI poll function %pS returned %d, exceeding its budget of %d.\n",
				n->poll, work, weight);

	if (likely(work < weight))
		return work;

