/* 학습 해설
 * NAPI 비활성화: callback 반환 대신 소유권 해제를 기다리기
 * 장치를 정리할 때 새 poll 예약을 막고 이미 가진 처리 소유권이 반환되기를 기다려야 합니다. 하지만 완료 API 호출과 드라이버 함수의 마지막 return은 같은 순간이 아니므로 기다림의 정확한 대상을 알아야 합니다.
 * napi_disable은 might_sleep 후 DISABLE을 설정합니다. SCHED 또는 NPSVC가 남아 있으면20~200마이크로초 usleep_range로 기다리며 상태를 다시 읽습니다. 비워지면 비교 교환으로 두 비트를 직접 설정해 비활성 상태의 소유권을 잡고 THREADED와 PREFER_BUSY_POLL을 지웁니다. 타이머를 취소한 뒤 DISABLE 비트를 내립니다.
 * DISABLE이 마지막에0이 돼도 활성 상태가 된 것은 아닙니다. SCHED와 NPSVC가 비활성화용 상태로 남습니다. napi_enable은 SCHED가 있는지 BUG_ON으로 검사하고 두 비트를 지우며 장치 threaded와 thread가 모두 있으면 THREADED를 더합니다. enable/disable을 임의로 반복해도 되는 멱등 API가 아닙니다.
 */
void napi_disable(struct napi_struct *n)
{
	unsigned long val, new;

	might_sleep();
	set_bit(NAPI_STATE_DISABLE, &n->state);

	val = READ_ONCE(n->state);
	do {
		while (val & (NAPIF_STATE_SCHED | NAPIF_STATE_NPSVC)) {
			usleep_range(20, 200);
			val = READ_ONCE(n->state);
		}

		new = val | NAPIF_STATE_SCHED | NAPIF_STATE_NPSVC;
		new &= ~(NAPIF_STATE_THREADED | NAPIF_STATE_PREFER_BUSY_POLL);
	} while (!try_cmpxchg(&n->state, &val, new));

	hrtimer_cancel(&n->timer);

	clear_bit(NAPI_STATE_DISABLE, &n->state);
}
EXPORT_SYMBOL(napi_disable);

/**
 *	napi_enable - enable NAPI scheduling
 *	@n: NAPI context
 *
 * Resume NAPI from being scheduled on this context.
 * Must be paired with napi_disable.
 */

